export const TINY_TRANSLATOR_JOURNEY_NAVIGATIONS = 6;

/**
 * The TinyTranslator specification, appended rather than woven in: it is the
 * first application in the corpus that declares either opt-in mechanism, and
 * keeping it whole is what lets a reader see the two declarations in one place.
 */
const angularTinyTranslatorSpec: AppSpec = {
	app: ANGULAR_TINY_TRANSLATOR_APP,
	framework: 'angular',
	/**
	 * The build record that pins the served migrated root, bound by the sha256 of
	 * its exact bytes: this record publishes a top-level `digest` over its own
	 * content rather than an `integrity.canonicalDigest`, so binding it by file
	 * bytes is the honest binding rather than a looser one.
	 *
	 * It is u22, the end of a chain of four: u17d's `dist-7` is the green
	 * deterministic build whose artifact never bootstraps, u19f's `dist-11` is the
	 * one that mounts and silently discards a typed translation, u19k's `dist-13`
	 * is the one that mounts and keeps it, and `dist-15` is that same lane rebuilt
	 * with the builder's font inliner off, so that building it asks nothing of
	 * anybody.
	 */
	canonicalReceipt: 'evidence/runs/angular-tiny-translator-v0-12-0/u22-offline-font-lane.json',
	canonicalDigest: '78a2094d74b2df53b5d2d0dbe52fc4eb928206a5b692a47143308a10ee567917',
	canonicalBinding: 'file-sha256',
	sources: {
		baseline: '.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
		migrated: '.versionless/stage/angular-tiny-translator-v0-12-0-u17b/dist-15',
	},
	initialRoute: TINY_TRANSLATOR_INITIAL_ROUTE,
	viewport: TINY_TRANSLATOR_VIEWPORT,
	consoleErrorInventory: WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS,
	failedRequestInventory: WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS,
	mockedNonLoopbackSeams: WITNESS_ANGULAR_TINY_TRANSLATOR_SEAMS,
	renderedStyleProbes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES,
	// The two opt-ins. Everything the journey is allowed to hand the page, and
	// the only reason its context accepts a download at all.
	fileInputs: { root, surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES },
	downloads: 'capture',
	transport: async (request) => await angularTinyTranslatorTransport(request),
	journey: async (context, page, _transportEvidence, lifecycle) => {
		if (lifecycle.expectedServiceWorker !== null)
			throw new Error('TinyTranslator journey received a service-worker expectation');
		const checkpoints = [
			await refusedServiceWorkerCheckpoint(
				lifecycle,
				'before-interactions',
				TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
			),
		];
		const measuredRoutes: WitnessMeasuredScrollAbsence['routes'] = [];
		/**
		 * The generic scroll measurement, taken at every stage. The application
		 * pins its container to the viewport and gives the unit list and the
		 * editor pane their own overflow, so a stage that started overflowing
		 * fails here rather than passing silently unexercised.
		 */
		const measure = async (stage: string): Promise<void> => {
			const extents = await lifecycle.viewportScroll();
			if (
				extents.clientHeight !== TINY_TRANSLATOR_VIEWPORT.height ||
				extents.scrollHeight > extents.clientHeight ||
				extents.scrollY !== 0
			)
				throw new Error(
					`TinyTranslator stage overflows the viewport the receipt says it does not: ${stage} ${canonicalize(extents)}`,
				);
			measuredRoutes.push({
				route: stage,
				scrollHeight: extents.scrollHeight,
				clientHeight: extents.clientHeight,
			});
		};
		const storageKeys = async (): Promise<string[]> => {
			const keys = await lifecycle.browserStorageKeys();
			if (keys.sessionStorage.length !== 0)
				throw new Error(
					`TinyTranslator wrote session storage the receipt says it does not: ${canonicalize(keys.sessionStorage)}`,
				);
			return tinyTranslatorStorageKeys(keys.localStorage);
		};
		await page.trackEvents('click', 'input', 'change', 'keydown');

		// (a) The empty application, on its own home route, before anything has
		// been handed to it.
		await context.expect.page.text(page, TT_APP_TITLE, 'Tiny Translator');
		await context.expect.page.bodyText(page, {
			contains: 'Currently there is no open project.',
		});
		const keysBeforeJourney = await storageKeys();
		await measure(TINY_TRANSLATOR_HOME_ROUTE);

		// (b) A genuine hover on the toolbar's project control, for the tooltip
		// the application renders into its own overlay.
		await page.hover(TT_EDIT_PROJECT_LINK);
		await context.expect.page.text(
			page,
			TT_TOOLTIP,
			'Details of the project (click to open)',
		);

		// (c) The create-project route, where every declared style probe exists
		// in both lanes: the toolbar, an icon, a raised button and the document.
		await page.click(TT_HOME_CREATE_LINK);
		await context.expect.page.exists(page, TT_CREATE_FORM);
		// The label the seam lives in also carries a `mat-icon`, and with the font
		// seam answered in-context that icon renders as its ligature TEXT — so the
		// element's exact text content is `open_in_browser` plus the seam, and
		// pinning it exactly would be pinning the icon degradation into an
		// assertion about a label. The label is asserted to exist, and the seam is
		// asserted as rendered text: mutating the seam in the served bundle takes
		// the string off the page and this assertion goes red on it.
		await context.expect.page.exists(page, TT_UPLOAD_LABEL);
		await context.expect.page.bodyText(page, { contains: TINY_TRANSLATOR_MUTATION_SEAM });
		const renderedStyles = await lifecycle.renderedStyles();
		const iconGroups = await lifecycle.groupedText(TT_ICON_PROBE);
		const renderedIcon = iconGroups[0]?.items[0];
		if (renderedIcon === undefined || renderedIcon.length === 0)
			throw new Error('TinyTranslator toolbar rendered no icon text to measure');
		const iconProbe = renderedStyles.find((probe) => probe.label === 'material-icon');
		const resolvedFontFamily = iconProbe?.properties['font-family'];
		if (resolvedFontFamily === undefined || resolvedFontFamily.length === 0)
			throw new Error('TinyTranslator icon probe resolved no font family');
		await measure(TINY_TRANSLATOR_CREATE_ROUTE);

		// (d) The project the journey creates through the application's own
		// form, with the synthetic translation file handed to the real hidden
		// file input. This load is the parity arbitration itself: the migrated
		// lane inserted a `typeof` guard into the FileReader service, and
		// nothing the build lanes ran observed the guarded statements. What
		// follows — the parse, and its digest — is that observation.
		await page.type(TT_PROJECT_NAME_INPUT, TT_PROJECT_NAME, { redact: false });
		const loaded = await lifecycle.loadFileInput('translation-file');
		if (
			loaded.fileName !== WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.fileName ||
			loaded.sha256 !== WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.sha256
		)
			throw new Error('TinyTranslator was handed a file the schema does not declare');
		await context.expect.page.bodyText(page, { contains: loaded.fileName });
		await context.expect.page.bodyText(page, {
			contains: `${WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits} entries`,
		});
		// The review workflow, so both state changes the application models are
		// reachable: a translator marks a unit translated, a reviewer marks it
		// final. The single-user workflow would collapse them into one.
		await page.click(TT_WORKFLOW_WITH_REVIEW);
		await page.click(TT_ADD_PROJECT_BUTTON);
		await context.expect.page.exists(page, TT_UNIT_LIST);
		await context.expect.page.count(
			page,
			TT_UNIT_LIST_ITEM,
			WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits,
		);
		const parsedUnits = await lifecycle.groupedText(TT_UNIT_PROBE);
		if (parsedUnits.length !== WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits)
			throw new Error('TinyTranslator parsed a different number of units than it rendered');
		await context.expect.page.bodyText(page, { contains: 'State new' });
		await measure(TINY_TRANSLATOR_TRANSLATE_ROUTE);

		// (e) A translation typed into the application's own editor, and the
		// state change the translator role can make.
		await page.click(`${TT_UNIT_LIST} mat-list-item:nth-of-type(1)`);
		await page.press(TT_TRANSLATION_INPUT, 'a', { modifiers: ['Meta'] });
		await page.type(TT_TRANSLATION_INPUT, TT_TRANSLATION_TEXT, { redact: false });
		// Measured: the editor propagates what was typed through a 200 ms debounce
		// of its own, so a commit issued on the last keystroke commits the message
		// the unit already had — the state changes and the text does not, and the
		// exported file says so. The application's own reaction to having taken
		// the edit is that its undo control stops being disabled, so that is what
		// the journey waits for: a wait on the application, not on a timer.
		await context.expect.page.attribute(page, TT_UNDO_BUTTON, 'disabled', null);
		await page.click(TT_MARK_TRANSLATED);
		// Measured: `markTranslated()` commits and the view advances to the next
		// unit, and the list's default filter is `Untranslated units`, so the unit
		// just translated leaves the list rather than re-rendering as
		// `State translated`. What the page shows instead is the project's own
		// progress reading, which is the application's account of the same fact.
		await context.expect.page.bodyText(page, { contains: '33 % translated' });

		// (f) The reviewer's state change, reached through the application's own
		// project editor rather than by rewriting its store.
		await page.click(TT_EDIT_PROJECT_LINK);
		await context.expect.page.exists(page, TT_EDIT_FORM);
		await page.click(TT_ROLE_REVIEWER);
		await page.click(TT_SAVE_PROJECT_BUTTON);
		await context.expect.page.bodyText(page, {
			contains: 'You are currently working as reviewer!',
		});
		// Measured: review mode alone does not put `mark as reviewed` on the page.
		// The control is rendered only for a unit whose state is `translated`, and
		// the editor is still holding the unit the translator's commit advanced to,
		// which is `new`. The application's own route back to the translated unit is
		// the `Review needed` filter it renders for exactly this step of the two-role
		// workflow: selecting it drops every other unit out of the view, and the one
		// unit left becomes the current one.
		await page.click(TT_FILTER_NEEDS_REVIEW);
		await context.expect.page.count(page, TT_UNIT_LIST_ITEM, 1);
		await context.expect.page.bodyText(page, { contains: 'State translated' });
		await page.click(TT_MARK_REVIEWED);
		// Measured: `markReviewed()` commits and the view is refreshed under the same
		// filter, so the unit the reviewer just made `final` leaves `Review needed` —
		// the list empties, and the editor, with no unit left to show, renders its
		// own empty surface rather than `State final`.
		await context.expect.page.count(page, TT_UNIT_LIST_ITEM, 0);
		await context.expect.page.bodyText(page, { contains: 'No Translation Unit' });
		// The reviewed state itself, read back through the filter that does show it:
		// all three units, the reviewed one first, carrying the state the reviewer
		// committed.
		//
		// Measured on both lanes, stage by stage, by
		// `packages/cli/src/fixture/angular-tiny-translator-allunits-probe-run.ts`:
		// the lanes agree at every stage of the reviewer half — three units on the
		// application's default `Untranslated` filter, two once the translator
		// commits, one under `Review needed`, none once the reviewer commits, and
		// three again with `All units` selected and `State final` on the page. The
		// earlier reading of two here was this journey clicking the radio HOST
		// rather than its label, which selects nothing: the list stayed on
		// `Untranslated`, and two is exactly what that filter shows at this point.
		// The count below is the application's own answer once the filter it was
		// asked for is the one it is on.
		await page.click(TT_FILTER_ALL);
		await context.expect.page.count(
			page,
			TT_UNIT_LIST_ITEM,
			WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits,
		);
		await page.click(`${TT_UNIT_LIST} mat-list-item:nth-of-type(1)`);
		await context.expect.page.bodyText(page, { contains: 'State final' });
		await measure(`${TINY_TRANSLATOR_TRANSLATE_ROUTE} (after the reviewed state change)`);

		// (g) The unit filter, narrowed by a typed substring and widened again
		// by a full clear rather than by re-selecting the unfiltered radio.
		await page.click(TT_FILTER_BY_SUBSTRING);
		await page.type(TT_FILTER_SUBSTRING_INPUT, TT_FILTER_TERM, { redact: false });
		await context.expect.page.count(page, TT_UNIT_LIST_ITEM, 1);
		await page.press(TT_FILTER_SUBSTRING_INPUT, 'a', { modifiers: ['Meta'] });
		await page.press(TT_FILTER_SUBSTRING_INPUT, 'Backspace');
		await context.expect.page.count(
			page,
			TT_UNIT_LIST_ITEM,
			WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits,
		);
		await page.click(TT_FILTER_ALL);

		// (h) The export, through the application's own downloader service. The
		// captured bytes are read back and parsed: an export that did not carry
		// the typed translation would be a download that happened and a file
		// that did not say anything.
		await page.click(TT_EXPORT_BUTTON);
		// Measured: the click returns as soon as the application has handed its
		// blob to the browser, and the browser finishes writing the file after
		// that — reading the capture ledger once, immediately, races it and finds
		// nothing. The download surface declares how many files this export
		// produces, so the settled ledger is polled under a fixed bound and
		// required to reach that count rather than accepted wherever it happened
		// to be. A ledger that never reaches it fails the assertion below.
		let captured = await lifecycle.capturedDownloads();
		for (
			let attempt = 0;
			attempt < 400 &&
			captured.length < WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE.expectedDownloads;
			attempt += 1
		) {
			await new Promise<void>((settle) => void setTimeout(settle, 25));
			captured = await lifecycle.capturedDownloads();
		}
		const exported = (await lifecycle.capturedDownloadTexts())[0];
		if (captured.length !== 1 || exported === undefined)
			throw new Error('TinyTranslator export produced no single captured download');
		if (
			!exported.includes(TT_EXPORTED_UNIT_ID) ||
			!exported.includes(TT_TRANSLATION_TEXT) ||
			!exported.includes('<target state="final"')
		)
			throw new Error('TinyTranslator export did not carry the typed translation');
		await measure(`${TINY_TRANSLATOR_TRANSLATE_ROUTE} (after the export)`);
		await context.expect.page.outcome(page, {
			events: {
				click: { atLeast: 8 },
				input: { atLeast: 2 },
				change: { atLeast: 2 },
				keydown: { atLeast: 4 },
			},
		});
		checkpoints.push(
			await refusedServiceWorkerCheckpoint(
				lifecycle,
				'after-interactions',
				TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
			),
		);

		// (i) A real document reload. There is no backend: the project lives in
		// browser local storage, and what comes back is what the journey put
		// there rather than a seed the harness supplied.
		await page.reload();
		// Measured on both lanes, stage by stage, by
		// `packages/cli/src/fixture/angular-tiny-translator-allunits-probe-run.ts`:
		// the reload restores the project out of local storage and the list comes
		// back on the application's OWN default filter — `Untranslated units` — so
		// what it renders is the two units nobody translated, not all three. The
		// unit the reviewer finalized is restored and simply outside that view,
		// which is the filter doing its job rather than data going missing; the two
		// steps below widen the view and read it back. Asserting three here was
		// asserting a filter state the application never restores.
		await context.expect.page.count(
			page,
			TT_UNIT_LIST_ITEM,
			WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits - 1,
		);
		await page.click(TT_FILTER_ALL);
		await context.expect.page.count(
			page,
			TT_UNIT_LIST_ITEM,
			WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE.transUnits,
		);
		// Measured: the restored list renders each unit's source and target
		// truncated, so the typed translation is not on the page until the unit is
		// opened. Opening it is what reads back both halves of the persistence
		// claim — the text the translator typed and the state the reviewer
		// committed, neither of which the harness put anywhere.
		await page.click(`${TT_UNIT_LIST} mat-list-item:nth-of-type(1)`);
		await context.expect.page.bodyText(page, { contains: TT_TRANSLATION_TEXT });
		await context.expect.page.bodyText(page, { contains: 'State final' });
		const keysAfterJourney = await storageKeys();
		await measure(`${TINY_TRANSLATOR_TRANSLATE_ROUTE} (after the online reload)`);
		checkpoints.push(
			await refusedServiceWorkerCheckpoint(
				lifecycle,
				'after-online-reload',
				TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
			),
		);
		await clean(
			context,
			page,
			TINY_TRANSLATOR_JOURNEY_NAVIGATIONS,
			lifecycle.expectedConsoleErrors,
			lifecycle.expectedFailedRequests,
		);
		const degradation = WITNESS_ANGULAR_TINY_TRANSLATOR_MAT_ICON_DEGRADATIONS[lifecycle.lane];
		if (
			resolvedFontFamily.includes(WITNESS_ANGULAR_TINY_TRANSLATOR_ICON_FONT_FAMILY) !==
			degradation.iconFontFamilyDeclared
		)
			throw new Error(
				`TinyTranslator ${lifecycle.lane} icon family disagrees with its declared degradation: ${resolvedFontFamily}`,
			);
		const applicationJourney: WitnessAngularTinyTranslatorJourney = {
			matIcon: {
				state: degradation.state,
				cause: degradation.cause,
				iconFontFamilyDeclared: degradation.iconFontFamilyDeclared,
				rendersLigatureText: true,
				masked: false,
				resolvedFontFamily,
				renderedText: renderedIcon,
			},
			fileReaderParity: {
				state: 'measured-identical-parse-across-lanes',
				assertion:
					'The application own file input was handed the synthetic translation file in both lanes, read by the capability-edited FileReader service, and the units it parsed were rendered and read back off the page. This journey IS the arbitration of the declared FileReader difference: the digest below is the parse itself, and it participates in the behavior digest the two lanes must agree on.',
				parsedUnits: parsedUnits.length,
				parsedDigest: sha256(canonicalize(parsedUnits)),
			},
			persistence: {
				store: 'browser-local-storage',
				service: 'the applications own BackendLocalStorageService behind BackendServiceAPI',
				backend: 'none',
				stubbed: false,
				keysBeforeJourney,
				keysAfterJourney,
				survivesOnlineReload: true,
			},
		};
		return {
			assertions: [
				'project created through the application own form on its own create-project route',
				'synthetic translation file handed to the application own hidden file input and parsed by its FileReader service',
				'parsed units rendered and read back off the page, identically in both lanes',
				'translation typed into the application own editor and marked translated by a translator',
				'reviewer role set through the application own project editor, the translated unit reached through the application own Review needed filter, and marked final',
				'the reviewed unit measured leaving the Review needed filter as the reviewer commits it, and its final state read back through the unfiltered list',
				'unit list narrowed by a typed substring and restored by a full clear',
				'translation file exported through the application own downloader and the captured bytes carrying the typed translation',
				'project tooltip reached by a genuine hover on the toolbar control',
				'project restored from browser local storage by an online reload, on the application own default filter, and the typed translation and the reviewed state read back off the restored unit',
				'a service-worker registration attempted at the literal `%BASE_HREF%ngsw-worker.js`, answered 400 and refused in both lanes, with nothing registered, installing, waiting, active, controlling or cached at any of the three checkpoints',
				'clean page',
			],
			offlineEvidence: { state: 'not-applicable' },
			refusedServiceWorker: {
				attempt: { ...TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT },
				checkpoints,
			},
			renderedStyles,
			applicationJourney,
			scrollAbsence: {
				state: 'measured-no-overflowing-document',
				viewport: { ...TINY_TRANSLATOR_VIEWPORT },
				routes: measuredRoutes,
				documentOverflow:
					'the application pins its container to the viewport and gives the unit list and the editor pane their own overflow, so no stage of the journey produces a scrollable document',
				claimed: false,
			},
		};
	},
};
apps.push(angularTinyTranslatorSpec);

/**
 * The TinyTranslator Witness specification, reachable so its declared
 * inventories, probes, seams and the two opt-in mechanisms can be checked
 * against the receipt schema that enforces them without launching a browser.
 */
export function angularTinyTranslatorWitnessSpec(): AppSpec {
	return angularTinyTranslatorSpec;
}

/**
 * Neither lane ships or registers a service worker, so the run is executed
 * under the zero-worker policy: the browser context still allows registration
 * and the journey is required to observe nothing at each of its checkpoints.
 */
export async function executeAngularTinyTranslatorWitnessRun(options: {
	lane: Lane;
	pass: 1 | 2;
	laneRoot: string;
	receiptRoot: string;
}): Promise<WitnessRealAppRun> {
	return await executeRun(angularTinyTranslatorSpec, options.lane, options.pass, {
		...options,
		serviceWorkerPolicy: 'zero',
	});
}

/**
 * The published application specs, exported so the two opt-in browser
 * mechanisms can be held to their own construction rather than to an intention:
 * a reader — and a test — can see directly that every vertical that predates
 * them declares neither a file-input surface nor a download surface, which is
 * what makes "those journeys are untouched" a checkable fact.
 */
export const witnessRealAppSpecs: readonly AppSpec[] = apps;

async function exists(file: string): Promise<boolean> {
	return access(file).then(
		() => true,
		() => false,

	return inventory;
}

function pageRecordFromReceipt(value: unknown): PageRecord {
	const receipt = value as { boxes?: Array<{ pages?: PageRecord[] }> };
	const page = receipt.boxes?.[0]?.pages?.[0];
	if (page === undefined)
		throw new Error('linked Witness receipt omitted the observed page record');
	return page;
}

function assertHmrFree(page: PageRecord): void {
	for (const url of [
		page.url,
		...page.navigations.map((navigation) => navigation.url),
		...page.networkRequests.map((request) => request.url),
	]) {
		const parsed = parseURL(url);
		const pathname = parsed.pathname || '';
		if (
			parsed.protocol === 'ws:' ||
			parsed.protocol === 'wss:' ||
			pathname === '/@vite/client' ||
			pathname.startsWith('/@id/') ||
			pathname.startsWith('/@fs/')
		)
			throw new Error(`Witness production-static journey imported HMR control: ${pathname}`);
	}
}

function normalizedRecord(
	page: PageRecord,
	normalizeRoute: (path: string) => string = (path) => path,
	admittedCancelledDuplicates: ReadonlySet<string> = new Set(),
	origin = '',
): WitnessRealAppRun['witnessRecord'] {
	return {
		interactions: page.interactions.map((interaction) => ({
			kind: interaction.kind as WitnessRealAppRun['interactions'][number]['kind'],
			selector:
				'selector' in interaction && typeof interaction.selector === 'string'
					? interaction.selector
					: 'viewport',
		})),
		navigationPaths: page.navigations.map((navigation) => {
			const parsed = parseURL(navigation.url);
			return normalizeRoute(`${parsed.pathname}${parsed.hash}`);
		}),
		trackedEventCounts: Object.fromEntries(
			Object.entries(page.trackedEvents).map(([name, events]) => [name, events.length]),
		),
		consoleErrors: page.consoleMessages.filter((message) => message.level === 'error').length,
		pageErrors: page.pageErrors.length,
		// Every browser-failed request except the ones the cancelled-duplicate
		// category admitted, which are recorded individually in their own
		// inventory. With no category declared the set is empty and this is the
		// plain total it has always been.
		failedRequests: page.failedRequests.filter(
			(request) =>
				!admittedCancelledDuplicates.has(
					failedRequestKey({
						method: request.method,
						path: witnessRecordedRequestPath(request.url, origin),
						reason: request.reason,
						count: 1,
					}),
				),
		).length,
	};
}

async function executeRun(
	app: AppSpec,
	lane: Lane,
	pass: 1 | 2,
	options: {
		laneRoot?: string;
		receiptRoot?: string;
		nextPrerenderPayload?: NextPrerenderPayloadInput;
		serviceWorkerPolicy?: 'canonical' | 'zero';
	} = {},
): Promise<WitnessRealAppRun> {
	const laneRoot = options.laneRoot ?? join(stageRoot, 'lanes', app.app, lane);
	const receiptDir = join(
		options.receiptRoot ?? join(stageRoot, 'witness-receipts'),
		app.app,
		lane,
		`pass-${pass}`,
	);
	await rm(receiptDir, { recursive: true, force: true });
	const beforeInventory = await staticInventory(laneRoot);
	const contextProfile =
		app.app === 'react-boilerplate' &&
		lane === 'baseline' &&
		options.serviceWorkerPolicy !== 'zero'
			? ('canonical-t060' as const)
			: ('current-witness' as const);
	const loopback = app.loopback?.();
	const staticServer = await startStaticServer(laneRoot, {
		profile: contextProfile,
		api: loopback?.api,
		upgrade: loopback?.upgrade,
	});
	const productionUrl = joinURL(staticServer.origin, app.initialRoute ?? '/');
	const transportEvidence: JourneyTransportEvidence = { apiUsernames: [] };
	const expectedServiceWorker =
		app.app === 'react-boilerplate' && options.serviceWorkerPolicy !== 'zero'
			? await expectedReactTelemetry(laneRoot, lane)
			: null;
	const phonecatOrdering =
		app.app === 'angular-phonecat' ? await expectedPhonecatOrdering(laneRoot) : null;
	const phonecatImages =
		app.app === 'angular-phonecat' ? await expectedPhonecatImages(laneRoot) : null;
	const differentialEvents: WitnessDifferentialEvent[] = [];
	const host = createPlaywrightWitnessHost({
		chromiumExecutable,
		contextProfile,
		transport:
			app.transport === undefined
				? undefined
				: async (request) => await app.transport!(request, transportEvidence),
		diagnosticEvent:
			options.serviceWorkerPolicy === 'zero' || app.serviceWorkers === 'block'
				? (event) => differentialEvents.push(event)
				: undefined,
		...(app.serviceWorkers === undefined ? {} : { serviceWorkers: app.serviceWorkers }),
		...(app.viewport === undefined ? {} : { viewport: app.viewport }),
		// Both mechanisms are per-application opt-ins and are spread in only
		// where the application declared them, so an application that declares
		// neither is run by exactly the host it was run by before they existed.
		...(app.fileInputs === undefined ? {} : { fileInputs: app.fileInputs }),
		...(app.downloads === undefined ? {} : { downloads: app.downloads }),
	});
	const expectedConsoleErrors = (app.consoleErrorInventory?.[lane] ?? []).reduce(
		(sum, entry) => sum + entry.count,
		0,
	);
	const expectedFailedRequests = (app.failedRequestInventory?.[lane] ?? []).reduce(
		(sum, entry) => sum + entry.count,
		0,
	);
	const cancelledDuplicateCategory = app.cancelledDuplicateFetches?.[lane] ?? [];
	const cancelledDuplicateFetchInventory = (): WitnessCancelledDuplicateFetchInventory =>
		buildCancelledDuplicateFetchInventory(
			host.requestOutcomes(),
			staticServer.origin,
			cancelledDuplicateCategory,
		);
	let journeyEvidence: JourneyEvidence | undefined;
	const definition = box(`${app.app}-${lane}-${pass}`, async (context) => {
		const page = await context.browser.visit(productionUrl);
		journeyEvidence = await app.journey(context, page, transportEvidence, {
			lane,
			serviceWorkerTelemetry: host.serviceWorkerTelemetry,
			staticRequests: staticServer.requests,
			expectedServiceWorker,
			phonecatOrdering,
			phonecatImages,
			viewportScroll: host.viewportScroll,
			expectedConsoleErrors,
			expectedFailedRequests,
			admittedCancelledDuplicateFetches: () => cancelledDuplicateFetchInventory().admitted,
			renderedStyles: async () => {
				const probes = app.renderedStyleProbes ?? [];
				if (probes.length === 0)
					throw new Error(`${app.app} declares no rendered-style probes to measure`);
				return await host.renderedStyles(probes);
			},
			groupedText: async (probe) => await host.groupedText(probe),
			browserStorageKeys: host.browserStorageKeys,
			loadFileInput: host.loadFileInput,
			capturedDownloads: host.capturedDownloads,
			capturedDownloadTexts: host.capturedDownloadTexts,
		});
		await context.receipt.capture('journey-complete');
	});
	let result: Awaited<ReturnType<typeof runBoxes>>;
	try {
		result = await runBoxes({
			root: laneRoot,
			boxes: [
				{
					file: join(laneRoot, 'versionless-runtime.box.ts'),
					relativeFile: 'versionless-runtime.box.ts',
					exportName: 'default',
					box: definition,
				},
			],
			receiptDir,
			assertionTimeoutMs: 10_000,
			fileSystem: witnessNodeFileSystem,
			browser: host.browser,
			headless: true,
		});
	} finally {
		await staticServer.close();
	}
	staticServer.assertClean();
	const afterInventory = await staticInventory(laneRoot);
	if (canonicalize(beforeInventory) !== canonicalize(afterInventory))
		throw new Error(`${app.app} ${lane} served bytes changed during the journey`);
	const rawReceipt = JSON.parse(await readFile(result.receiptPath, 'utf8')) as unknown;
	const completedJourney = journeyEvidence as JourneyEvidence | undefined;
	const observerFinalization = host.serviceWorkerObserverFinalization();
	if (completedJourney?.timeoutTelemetry !== undefined) {
		const diagnostic = {
			schemaVersion: 'versionless.witness-real-app-sw-diagnostic.v1',
			result: 'timeout',
			app: app.app,
			lane,
			pass,
			telemetry: completedJourney.timeoutTelemetry,
			observerFinalization,
			staticLedger: staticServer.ledger(),
		};
		const diagnosticDirectory = join(stageRoot, 'diagnostics');
		await mkdir(diagnosticDirectory, { recursive: true });
		await writeFile(
			join(diagnosticDirectory, `${app.app}-${lane}-service-worker.json`),
			`${canonicalize(diagnostic)}\n`,
		);
		throw new Error(
			`linked Witness service-worker diagnostic timed out: ${canonicalize({ telemetry: diagnostic.telemetry, failedResponses: diagnostic.staticLedger.filter((entry) => entry.status !== 200) })}`,
		);
	}
	if (result.status !== 'passed' || completedJourney === undefined)
		throw new Error(
			`linked Witness runtime journey failed: ${result.boxes[0]?.error?.message ?? 'unknown failure'}; static paths: ${canonicalize(staticServer.requests())}`,
		);
	const pageRecord = pageRecordFromReceipt(rawReceipt);
	const serviceWorkerRequests = projectServiceWorkerEvents(
		differentialEvents.filter(
			(event) =>
				event.detail.serviceWorker === true ||
				event.urlPath === '/sw.js' ||
				event.urlPath === '/service-worker.js',
		),
	);
	const legacyMainPrecache =
		app.app === 'react-boilerplate' &&
		lane === 'baseline' &&
		options.serviceWorkerPolicy !== 'zero'
			? {
					state: 'exact-completed' as const,
					responses: await exactLegacyMainPrecacheResponses(
						laneRoot,
						staticServer.ledger(),
					),
				}
			: { state: 'not-applicable' as const };
	const nextPrerenderPayload =
		options.nextPrerenderPayload === undefined
			? ({ state: 'not-applicable' } as const)
			: exactNextPrerenderPayloadEvidence(
					laneRoot,
					staticServer.ledger(),
					options.nextPrerenderPayload,
				);
	assertHmrFree(pageRecord);
	/**
	 * Computed once from the whole run's ledger, before anything is counted, so
	 * the failed-request inventory and the recorded failure count both see the
	 * same admitted set.
	 */
	const cancelledDuplicates = cancelledDuplicateFetchInventory();
	const admittedCancelledKeys = new Set(
		cancelledDuplicates.observed.map(cancelledDuplicateFetchKey),
	);
	const witnessRecord = normalizedRecord(
		pageRecord,
		app.normalizeRoute,
		admittedCancelledKeys,
		staticServer.origin,
	);
	const interactions = witnessRecord.interactions;
	const trackedEvents = Object.entries(witnessRecord.trackedEventCounts)
		.filter(([, count]) => count > 0)
		.map(([name]) => name)
		.sort();
	const runWithoutDigest = {
		app: app.app,
		framework: app.framework,
		lane,
		interactions,
		assertions: completedJourney.assertions,
		routes: witnessRecord.navigationPaths,
		trackedEvents,
		witnessRecord,
		cleanPage: true as const,
		offlineEvidence: completedJourney.offlineEvidence,
		servedStatic: {
			transport: 'isolated-bounded-loopback-production-static' as const,
			documentFallback: 'index-only' as const,
			missingAssets: '404' as const,
			traversal: 'rejected' as const,
			inventory: {
				files: beforeInventory.files,
				beforeSha256: beforeInventory.digest,
				afterSha256: afterInventory.digest,
			},
			application: {
				path: 'index.html' as const,
				beforeSha256: beforeInventory.applicationSha256,
				afterSha256: afterInventory.applicationSha256,
			},
			serviceWorkers: beforeInventory.serviceWorkers.map((serviceWorker, index) => ({
				path: serviceWorker.path,
				beforeSha256: serviceWorker.sha256,
				afterSha256: afterInventory.serviceWorkers[index]!.sha256,
			})),
			byteIdentical: true as const,
			hmrControls: false as const,
			legacyMainPrecache,
			phonecatOrdering:
				phonecatOrdering === null
					? { state: 'not-applicable' as const }
					: {
							state: 'data-derived-full-order' as const,
							datasetSha256: phonecatOrdering.datasetSha256,
							orderSha256: phonecatOrdering.orderSha256,
							rows: 20 as const,
							comparator: 'stable-lowercase-utf16-source-order-ties' as const,
						},
			phonecatImageTransition:
				phonecatImages === null
					? { state: 'not-applicable' as const }
					: {
							state: 'data-derived-visible-transition' as const,
							detailSha256: phonecatImages.detailSha256,
							defaultImage: phonecatImages.defaultImage,
							nonDefaultImage: phonecatImages.nonDefaultImage,
							hover: 'genuine-thumbnail-mouseover' as const,
							transition: 'genuine-ng-click' as const,
							heroVisibility: 'genuine-hover' as const,
						},
			nextPrerenderPayload,
		},
		observerFinalization,
		...(completedJourney.zeroServiceWorker === undefined
			? {}
			: {
					zeroServiceWorker: {
						...completedJourney.zeroServiceWorker,
						outputFiles: beforeInventory.serviceWorkers,
						requests: differentialEvents.filter(
							(event) =>
								event.detail.serviceWorker === true ||
								event.urlPath === '/sw.js' ||
								event.urlPath === '/service-worker.js',
						),
						workerEvents: observerFinalization.workerEvents,
					},
				}),
		...(completedJourney.refusedServiceWorker === undefined
			? {}
			: {
					refusedServiceWorker: {
						...completedJourney.refusedServiceWorker,
						outputFiles: beforeInventory.serviceWorkers,
						/**
						 * The same projection the blocked-runtime shape uses. The wall
						 * clock and the run-global sequence number are dropped because
						 * they cannot reproduce; who observed the request, in what
						 * phase, for which path and with what detail is identical run
						 * to run. This is the first shape in which the difference is
						 * visible: an application that never asks produces no requests
						 * here, and this one produces the registration it is refused.
						 */
						requests: serviceWorkerRequests,
						workerEvents: observerFinalization.workerEvents,
					},
				}),
		...(completedJourney.zeroServiceWorkerRuntime === undefined
			? {}
			: {
					zeroServiceWorkerRuntime: {
						...completedJourney.zeroServiceWorkerRuntime,
						emittedOutputFiles: beforeInventory.serviceWorkers,
						requests: differentialEvents.filter(
							(event) =>
								event.detail.serviceWorker === true ||
								event.urlPath === '/sw.js' ||
								event.urlPath === '/service-worker.js',
						),
						workerEvents: observerFinalization.workerEvents,
					},
				}),
		...(completedJourney.blockedServiceWorkerRuntime === undefined
			? {}
			: {
					blockedServiceWorkerRuntime: {
						...completedJourney.blockedServiceWorkerRuntime,
						emittedOutputFiles: beforeInventory.serviceWorkers,
						requests: serviceWorkerRequests,
						requestTally: tallyServiceWorkerEvents(serviceWorkerRequests),
						workerEvents: observerFinalization.workerEvents,
					},
				}),
		...(completedJourney.scrollSurface === undefined
			? {}
			: { scrollSurface: completedJourney.scrollSurface }),
		...(completedJourney.scrollAbsence === undefined
			? {}
			: { scrollAbsence: completedJourney.scrollAbsence }),
		...(app.consoleErrorInventory === undefined
			? {}
			: {
					consoleErrorInventory: buildConsoleErrorInventory(
						pageRecord,
						staticServer.origin,
						app.consoleErrorInventory[lane],
					),
				}),
		...(app.failedRequestInventory === undefined
			? {}
			: {
					failedRequestInventory: buildFailedRequestInventory(
						pageRecord,
						staticServer.origin,
						app.failedRequestInventory[lane],
						admittedCancelledKeys,
					),
				}),
		...(app.cancelledDuplicateFetches === undefined
			? {}
			: { cancelledDuplicateFetches: cancelledDuplicates }),
		...(app.mockedNonLoopbackSeams === undefined
			? {}
			: {
					mockedNonLoopbackSeams: buildMockedNonLoopbackSeamInventory(
						host.requestOutcomes(),
						staticServer.origin,
						app.mockedNonLoopbackSeams[lane],
					),
				}),
		// Both opt-in mechanisms report themselves only where the application
		// declared them. An application that declared neither carries neither
		// key, so the absence of the mechanism is visible in the evidence rather
		// than having to be taken on trust.
		...(app.fileInputs === undefined
			? {}
			: {
					fileInputLoads: buildFileInputLoadInventory(
						app.fileInputs.surfaces,
						host.loadedFileInputs(),
					),
				}),
		...(app.downloads === undefined
			? {}
			: {
					downloadCaptures: buildDownloadCaptureInventory(await host.capturedDownloads()),
				}),
		...(completedJourney.renderedStyles === undefined
			? {}
			: {
					renderedStyles: {
						state: 'measured-resolved-styles' as const,
						probes: completedJourney.renderedStyles,
					} satisfies WitnessRenderedStyleEvidence,
				}),
		...(completedJourney.applicationJourney === undefined
			? {}
			: { applicationJourney: completedJourney.applicationJourney }),
		successfulNonLoopback: host.locality().successfulNonLoopback,
	};
	if ('blockedServiceWorkerRuntime' in runWithoutDigest) {
		const blocked = runWithoutDigest.blockedServiceWorkerRuntime;
		if (
			blocked === undefined ||
			blocked.registration !== 'application-register-refused-by-context' ||
			blocked.workerEvents.length !== 0 ||
			blocked.checkpoints.length !== 3 ||
			blocked.checkpoints.some(
				(checkpoint) =>
					checkpoint.state !== 'timeout' ||
					checkpoint.registrations !== 0 ||
					checkpoint.controller !== null ||
					checkpoint.cacheNames.length !== 0 ||
					checkpoint.workerEvents.length !== 0,
			)
		)
			throw new Error('blocked-service-worker policy assertion failed');
	}
	if ('zeroServiceWorker' in runWithoutDigest) {
		const zero = runWithoutDigest.zeroServiceWorker;
		if (
			zero === undefined ||
			zero.outputFiles.length !== 0 ||
			zero.requests.length !== 0 ||
			zero.workerEvents.length !== 0 ||
			zero.checkpoints.length !== 3 ||
			zero.checkpoints.some(
				(checkpoint) =>
					checkpoint.state !== 'timeout' ||
					checkpoint.registrations !== 0 ||
					checkpoint.controller !== null ||
					checkpoint.cacheNames.length !== 0 ||
					checkpoint.workerEvents.length !== 0,
			)
		)
			throw new Error('zero-service-worker policy assertion failed');
	}
	if ('zeroServiceWorkerRuntime' in runWithoutDigest) {
		const zero = runWithoutDigest.zeroServiceWorkerRuntime;
		if (
			zero === undefined ||
			zero.registration !== 'application-unregister' ||
			zero.requests.length !== 0 ||
			zero.workerEvents.length !== 0 ||
			zero.checkpoints.length !== 3 ||
			zero.checkpoints.some(
				(checkpoint) =>
					checkpoint.state !== 'timeout' ||
					checkpoint.registrations !== 0 ||
					checkpoint.controller !== null ||
					checkpoint.cacheNames.length !== 0 ||
					checkpoint.workerEvents.length !== 0,
			)
		)
			throw new Error('runtime zero-service-worker policy assertion failed');
	}
	return {
		...runWithoutDigest,
		pass,
		result: 'pass',
		semanticDigest: sha256(canonicalize(runWithoutDigest)),
	};
}

